.novelslist2 li .s2 a<js>
result
  .toArray()
  .slice(0, 3)
  .map(function (a) {
    var url = String(a.attr('href')).replace(
      /^\/([^\/])/,
      baseUrl.match(/(.+\/\/.+?\/)/)[1] + '$1'
    );
